// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.connectivity.callimport com.roshan.persona.connectivity.model.CallDirectionimport com.roshan.persona.connectivity.model.CallStateimport com.roshan.persona.connectivity.model.SpamClassificationimport com.roshan.persona.connectivity.model.SpamLevelimport com.roshan.persona.connectivity.model.SpamSource/** * NOUS — Call Services (Module 11 v3 — Step 11.3). * * Service interfaces for call operations — wraps Android's TelecomManager * + CallLog for testability. */// ──────────────────────────────────────────────────────────────────────────// Call Service (wraps TelecomManager)// ──────────────────────────────────────────────────────────────────────────/** * Interface for placing/answering/rejecting calls. * * Real implementation ([AndroidCallService]) wraps TelecomManager. * Tests inject a fake. */interface CallService {    /** Place a call to [phoneNumber] using [simSlot] (null = default SIM). */    suspend fun placeCall(phoneNumber: String, simSlot: Int? = null): Boolean    /** Answer the current incoming call. */    suspend fun answerCall(): Boolean    /** Reject the current incoming call. */    suspend fun rejectCall(): Boolean    /** Hang up the current call. */    suspend fun endCall(): Boolean    /** Get the current call state. */    fun getCallState(): CallState    /** True if the device supports phone calls (has telephony). */    fun isAvailable(): Boolean}// ──────────────────────────────────────────────────────────────────────────// Call Log Service (wraps CallLog.Calls)// ──────────────────────────────────────────────────────────────────────────/** * Interface for reading call logs. * * Real implementation ([AndroidCallLogService]) wraps CallLog.Calls. * Tests inject a fake. */interface CallLogService {    /** Get call log entries since [sinceMs]. */    suspend fun getCallLog(sinceMs: Long): List<CallLogEntry>    /** Get missed calls since [sinceMs]. */    suspend fun getMissedCalls(sinceMs: Long): List<CallLogEntry>    /** Delete a call log entry by ID. */    suspend fun deleteEntry(id: String): Boolean    /** Delete all call log entries. */    suspend fun deleteAll(): Int}/** One call log entry. */data class CallLogEntry(    val id: String,    val phoneNumber: String,    val displayName: String?,    val direction: CallDirection,    val timestampMs: Long,    val durationSeconds: Long,)// ──────────────────────────────────────────────────────────────────────────// Spam Database (local, on-device)// ──────────────────────────────────────────────────────────────────────────/** * Interface for the local spam database. * * Real implementation uses Room (a dedicated `spam_numbers` table). * Tests inject an in-memory fake. * * ## Privacy * * All spam data is on-device only. The database is populated by: *  1. User reports ("Mark this number as spam"). *  2. Community updates (downloaded via secure patches — no cloud sync). *  3. Pattern detection (auto-added when frequency threshold exceeded). */interface SpamDatabase {    /** Look up a phone number in the spam database. */    suspend fun lookup(phoneNumber: String): SpamClassification?    /** Report a number as spam (user-initiated). */    suspend fun reportSpam(phoneNumber: String, reason: String)    /** Remove a number from the spam database (false positive). */    suspend fun removeFromSpam(phoneNumber: String): Boolean    /** Get all spam numbers (for UI — Settings → Connectivity → Blocked Numbers). */    suspend fun getAllSpamNumbers(): List<SpamClassification>    /** Get the count of calls from [phoneNumber] in the last [hours]. */    suspend fun getCallCount(phoneNumber: String, hours: Int): Int    /** Record that a call was received from [phoneNumber] (for pattern detection). */    suspend fun recordCall(phoneNumber: String, timestampMs: Long)}